            self.advance()
            result = self.expr_()
            if self.current_char == ')':
                self.advance()
                return result
            self.error()
        elif self.current_char.isdigit() or (self.current_char == '-' and (self.pos == 0 or self.expr[self.pos - 1] == '(')):
            return self.number()
        self.error()

    def term(self) -> float:
        result = self.factor()
        while self.current_char is not None and self.current_char in ('*', '/'):
            op = self.current_char
            self.advance()
            if op == '*':
                result *= self.factor()
            elif op == '/':
                result /= self.factor()
        return result

    def expr_(self) -> float:
        result = self.term()
