class Evaluator:
    def __init__(self, expression: str):
        self.tokens = self.tokenize(expression)
        self.current = 0

    def tokenize(self, expr: str):
        tokens = []
        num = ''
        for char in expr:
            if char.isdigit() or char == '.':
                num += char
            else:
                if num:
                    tokens.append(float(num))
                    num = ''
                if char in '+-*/()':
                    tokens.append(char)
        if num:
            tokens.append(float(num))
        return tokens

    def parse_expression(self):
        value = self.parse_term()
        while self.current < len(self.tokens):
            token = self.tokens[self.current]
            if token == '+':
                self.current += 1
                value += self.parse_term()
            elif token == '-':
                self.current += 1
                value -= self.parse_term()
            else:
                break
        return value

    def parse_term(self):
        value = self.parse_factor()
        while self.current < len(self.tokens):
            token = self.tokens[self.current]
            if token == '*':
                self.current += 1
                value *= self.parse_factor()
            elif token == '/':
                self.current += 1
                denominator = self.parse_factor()
                if denominator == 0:
                    raise ValueError("Division by zero.")
                value /= denominator
            else:
                break
        return value

    def parse_factor(self):
        token = self.tokens[self.current]
        if isinstance(token, float):
            self.current += 1
            return token
        elif token == '(':
            self.current += 1
            value = self.parse_expression()
            if self.tokens[self.current] == ')':
                self.current += 1
            return value
        else:
            raise ValueError("Invalid syntax")

def evaluate(expr: str) -> float:
    """
    Evaluates the given arithmetic expression using a recursive descent parser.
    This approach allows handling operator precedence and parentheses correctly.
    """
    evaluator = Evaluator(expr)
    result = evaluator.parse_expression()
